cat << 'EOF' > debug_g.py
import pandas as pd
import json

payments = pd.read_csv('/data/payments.csv')
fees = json.load(open('/data/fees.json'))
merchant_data = json.load(open('/data/merchant_data.json'))
merchant_name = "Belles_cookbook_store"
m_info = next(m for m in merchant_data if m['merchant'] == merchant_name)
jan_payments = payments[(payments['merchant'] == merchant_name) & (payments['day_of_year'] <= 31)]
fraud_txs = jan_payments[jan_payments['has_fraudulent_dispute'] == True]

vol_cat = "100k-1m"
fraud_cat = ">8.3%"
capture_delay_cat = "<3"
acquirer_country = "US"

def matches(rule, tx, aci_override):
    if rule['card_scheme'] != tx['card_scheme']: return False
    if rule['account_type'] and m_info['account_type'] not in rule['account_type']: return False
    if rule['capture_delay'] and rule['capture_delay'] != capture_delay_cat: return False
    if rule['monthly_fraud_level'] and rule['monthly_fraud_level'] != fraud_cat: return False
    if rule['monthly_volume'] and rule['monthly_volume'] != vol_cat: return False
    if rule['merchant_category_code'] and m_info['merchant_category_code'] not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: return False
    if rule['aci'] and aci_override not in rule['aci']: return False
    if rule['intracountry'] is not None:
        is_intra = 1.0 if tx['issuing_country'] == acquirer_country else 0.0
        if rule['intracountry'] != is_intra: return False
    return True

tx = fraud_txs.iloc[0]
print(f"Transaction: card_scheme={tx['card_scheme']}, is_credit={tx['is_credit']}, aci={tx['aci']}, issuing={tx['issuing_country']}")
matching = [r['ID'] for r in fees if matches(r, tx, 'G')]
print(f"Matching rule IDs for G: {matching}")

# Check rules for this card scheme and ACI G
relevant_rules = [r for r in fees if r['card_scheme'] == tx['card_scheme'] and (not r['aci'] or 'G' in r['aci'])]
print(f"Number of relevant rules for {tx['card_scheme']} and G: {len(relevant_rules)}")
for r in relevant_rules:
    # Check why it doesn't match
    reasons = []
    if rule_at := r['account_type']:
        if m_info['account_type'] not in rule_at: reasons.append(f"account_type {rule_at}")
    if rule_cd := r['capture_delay']:
        if rule_cd != capture_delay_cat: reasons.append(f"capture_delay {rule_cd}")
    if rule_fl := r['monthly_fraud_level']:
        if rule_fl != fraud_cat: reasons.append(f"fraud_level {rule_fl}")
    if rule_vc := r['monthly_volume']:
        if rule_vc != vol_cat: reasons.append(f"volume {rule_vc}")
    if rule_mcc := r['merchant_category_code']:
        if m_info['merchant_category_code'] not in rule_mcc: reasons.append(f"mcc {rule_mcc}")
    if (rule_ic := r['is_credit']) is not None:
        if rule_ic != tx['is_credit']: reasons.append(f"is_credit {rule_ic}")
    if (rule_intra := r['intracountry']) is not None:
        is_intra = 1.0 if tx['issuing_country'] == acquirer_country else 0.0
        if rule_intra != is_intra: reasons.append(f"intracountry {rule_intra}")
    print(f"Rule {r['ID']}: reasons: {reasons}")
EOF
